values
('bmlt-hematology-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The primary function of red blood cells is to:","translation":"Red blood cell को मुख्य काम के हो?","options":["Transport oxygen","Produce antibodies","Form bile","Digest proteins"],"correctIndex":0,"explanation":"Hemoglobin in RBCs carries oxygen to tissues.","explanationNe":"RBC को hemoglobin ले oxygen tissue सम्म पुर्‍याउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The normal adult hemoglobin molecule contains:","translation":"वयस्क hemoglobin molecule मा के हुन्छ?","options":["Four globin chains and four heme groups","Two globin chains only","One heme group only","Six globin chains"],"correctIndex":0,"explanation":"Adult HbA is a tetramer with two alpha and two beta chains, each associated with heme.","explanationNe":"Adult HbA मा दुई alpha र दुई beta chain हुन्छन्; प्रत्येकसँग heme हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"The average lifespan of a normal circulating RBC is approximately:","translation":"सामान्य circulating RBC को औसत आयु कति हुन्छ?","options":["120 days","7 days","30 days","365 days"],"correctIndex":0,"explanation":"Normal RBCs circulate for about 120 days.","explanationNe":"सामान्य RBC करिब १२० दिन circulation मा रहन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Reticulocytes are:","translation":"Reticulocyte भनेको के हो?","options":["Immature red cells containing residual RNA","Mature neutrophils","Platelet fragments only","Mature lymphocytes"],"correctIndex":0,"explanation":"Reticulocytes are newly released RBCs that retain residual ribosomal RNA.","explanationNe":"Reticulocyte नयाँ निस्केका RBC हुन् जसमा residual ribosomal RNA हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which stain is commonly used for reticulocyte counting?","translation":"Reticulocyte count का लागि कुन stain प्रयोग हुन्छ?","options":["New methylene blue","Gram stain","Ziehl-Neelsen stain","India ink"],"correctIndex":0,"explanation":"New methylene blue is a supravital stain used to demonstrate reticulocyte RNA.","explanationNe":"New methylene blue supravital stain ले reticulocyte RNA देखाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"MCV measures the:","translation":"MCV ले के मापन गर्छ?","options":["Average volume of red blood cells","Average hemoglobin concentration in whole blood","Platelet number","WBC percentage"],"correctIndex":0,"explanation":"MCV is the mean corpuscular volume and classifies anemia by cell size.","explanationNe":"MCV ले RBC को औसत volume मापन गरी anemia लाई cell size अनुसार वर्गीकरण गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"MCHC represents the:","translation":"MCHC ले के जनाउँछ?","options":["Average concentration of hemoglobin in packed RBC volume","Total number of RBCs","Average platelet size","Total WBC count"],"correctIndex":0,"explanation":"MCHC is the mean concentration of hemoglobin within red cells.","explanationNe":"MCHC ले RBC भित्र hemoglobin को औसत concentration जनाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Microcytic hypochromic anemia is commonly associated with:","translation":"Microcytic hypochromic anemia कुनसँग सम्बन्धित हुन्छ?","options":["Iron deficiency","Vitamin B12 deficiency","Acute blood loss only","Aplastic anemia"],"correctIndex":0,"explanation":"Iron deficiency commonly produces small, pale red cells.","explanationNe":"Iron deficiency मा RBC साना र फिका देखिन सक्छन्।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Macrocytosis is commonly seen in deficiency of:","translation":"Macrocytosis कुन vitamin को कमीमा देखिन्छ?","options":["Vitamin B12 or folate","Vitamin C only","Vitamin K only","Vitamin A only"],"correctIndex":0,"explanation":"B12 or folate deficiency impairs DNA synthesis and can cause megaloblastic macrocytosis.","explanationNe":"B12 वा folate कमीले DNA synthesis बिगारी macrocytosis गराउन सक्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"A characteristic blood film finding in iron deficiency anemia is:","translation":"Iron deficiency anemia मा blood film को विशेषता कुन हो?","options":["Microcytic hypochromic cells","Macro-ovalocytes only","Sickle cells in every case","Auer rods"],"correctIndex":0,"explanation":"Iron deficiency typically causes microcytosis and hypochromia; anisopoikilocytosis may occur.","explanationNe":"Iron deficiency मा microcytosis र hypochromia तथा anisopoikilocytosis हुन सक्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which cell is primarily responsible for antibody production after differentiation?","translation":"Differentiation पछि antibody उत्पादन गर्ने cell कुन हो?","options":["Plasma cell","Neutrophil","Eosinophil","Platelet"],"correctIndex":0,"explanation":"B lymphocytes can differentiate into plasma cells that secrete antibodies.","explanationNe":"B lymphocyte plasma cell मा बदलिई antibody secretion गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"The most abundant leukocyte in normal adult peripheral blood is usually:","translation":"सामान्य वयस्क peripheral blood मा सबैभन्दा धेरै leukocyte कुन हुन्छ?","options":["Neutrophil","Basophil","Eosinophil","Monocyte"],"correctIndex":0,"explanation":"Neutrophils usually form the largest proportion of circulating leukocytes.","explanationNe":"Neutrophil सामान्यतया circulating leukocyte को सबैभन्दा ठूलो हिस्सा हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Eosinophilia is commonly associated with:","translation":"Eosinophilia कुनसँग सामान्यतया सम्बन्धित हुन्छ?","options":["Allergy or parasitic infection","Iron deficiency alone","Hemophilia","ABO incompatibility"],"correctIndex":0,"explanation":"Eosinophils may increase in allergic disorders and some parasitic infections.","explanationNe":"Allergy र केही parasitic infection मा eosinophil बढ्न सक्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"A band cell is an immature form of:","translation":"Band cell कुनको immature form हो?","options":["Neutrophil","Lymphocyte","Eosinophil","Monocyte"],"correctIndex":0,"explanation":"Band neutrophils are less mature than segmented neutrophils.","explanationNe":"Band neutrophil segmented neutrophil भन्दा कम mature हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"A left shift in the neutrophil series generally indicates increased:","translation":"Neutrophil series मा left shift ले के बढेको जनाउँछ?","options":["Immature neutrophils in blood","Mature eosinophils only","Platelet fragments","Reticulocytes"],"correctIndex":0,"explanation":"A left shift refers to increased immature neutrophil forms, often during acute infection or inflammation.","explanationNe":"Left shift भनेको immature neutrophil बढ्नु हो, प्रायः acute infection/inflammation मा।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"The normal platelet function is mainly to:","translation":"Platelet को मुख्य काम के हो?","options":["Participate in primary hemostasis","Carry most oxygen","Produce immunoglobulin","Synthesize albumin"],"correctIndex":0,"explanation":"Platelets adhere, activate and aggregate to form the primary hemostatic plug.","explanationNe":"Platelet ले adhere, activate र aggregate भएर primary hemostatic plug बनाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Thrombocytopenia means:","translation":"Thrombocytopenia भन्नाले के बुझिन्छ?","options":["Low platelet count","High platelet count","Low hemoglobin only","High WBC count"],"correctIndex":0,"explanation":"Thrombocytopenia is a platelet count below the laboratory reference range.","explanationNe":"Thrombocytopenia भनेको platelet count reference range भन्दा कम हुनु हो।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Which anticoagulant is preferred for a routine CBC?","translation":"Routine CBC का लागि कुन anticoagulant उपयुक्त हुन्छ?","options":["EDTA","Sodium fluoride","Plain citrate only","Oxalate only"],"correctIndex":0,"explanation":"EDTA preserves cellular morphology and is routinely used for CBC specimens.","explanationNe":"EDTA ले cellular morphology जोगाउँछ र CBC मा प्रयोग हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"The usual blood-to-anticoagulant ratio in a citrate tube for coagulation tests is:","translation":"Coagulation test को citrate tube मा blood र anticoagulant को सामान्य ratio कुन हो?","options":["9:1","1:9","4:1","1:1"],"correctIndex":0,"explanation":"Standard coagulation tubes use nine parts blood to one part citrate.","explanationNe":"Coagulation tube मा सामान्यतया ९ भाग blood र १ भाग citrate हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"PT primarily evaluates the:","translation":"PT ले मुख्यतः कुन pathway मूल्यांकन गर्छ?","options":["Extrinsic and common pathways","Intrinsic pathway only","Platelet count","Fibrinolysis only"],"correctIndex":0,"explanation":"PT assesses the extrinsic and common coagulation pathways.","explanationNe":"PT ले extrinsic र common coagulation pathway मूल्यांकन गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"aPTT primarily evaluates the:","translation":"aPTT ले मुख्यतः कुन pathway मूल्यांकन गर्छ?","options":["Intrinsic and common pathways","Extrinsic pathway only","RBC production","Platelet morphology"],"correctIndex":0,"explanation":"aPTT assesses intrinsic and common pathway factors.","explanationNe":"aPTT ले intrinsic र common pathway factor मूल्यांकन गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"Which factor is also known as fibrinogen?","translation":"Fibrinogen कुन coagulation factor हो?","options":["Factor I","Factor II","Factor V","Factor X"],"correctIndex":0,"explanation":"Fibrinogen is coagulation factor I and is converted to fibrin by thrombin.","explanationNe":"Fibrinogen factor I हो र thrombin ले fibrin मा बदल्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"Thrombin converts fibrinogen into:","translation":"Thrombin ले fibrinogen लाई केमा बदल्छ?","options":["Fibrin","Plasmin","Prothrombin","Albumin"],"correctIndex":0,"explanation":"Thrombin cleaves fibrinogen to form fibrin strands.","explanationNe":"Thrombin ले fibrinogen बाट fibrin strand बनाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Vitamin K is required for synthesis of which clotting factors?","translation":"कुन clotting factor synthesis का लागि Vitamin K चाहिन्छ?","options":["II, VII, IX and X","I, V and VIII only","XI and XII only","All factors equally"],"correctIndex":0,"explanation":"Vitamin K-dependent factors include II, VII, IX and X, plus proteins C and S.","explanationNe":"Vitamin K dependent factor II, VII, IX, X तथा protein C र S हुन्।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Hemophilia A is caused by deficiency of:","translation":"Hemophilia A कुन factor को कमीले हुन्छ?","options":["Factor VIII","Factor IX","Factor VII","Factor XIII"],"correctIndex":0,"explanation":"Hemophilia A is due to factor VIII deficiency or dysfunction.","explanationNe":"Hemophilia A factor VIII कमी वा dysfunction ले हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"Hemophilia B is caused by deficiency of:","translation":"Hemophilia B कुन factor को कमीले हुन्छ?","options":["Factor IX","Factor VIII","Factor V","Factor I"],"correctIndex":0,"explanation":"Hemophilia B is due to factor IX deficiency or dysfunction.","explanationNe":"Hemophilia B factor IX कमी वा dysfunction ले हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"The ESR is commonly measured by the:","translation":"ESR सामान्यतया कुन विधिबाट मापन गरिन्छ?","options":["Westergren method","Coombs method","Duke method","Bleeding time only"],"correctIndex":0,"explanation":"The Westergren method is a widely used reference method for ESR.","explanationNe":"Westergren method ESR का लागि व्यापक प्रयोग हुने reference method हो।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"ESR may be increased in:","translation":"ESR कुन अवस्थामा बढ्न सक्छ?","options":["Inflammation and some infections","Every healthy person equally","Only thrombocytopenia","Only hemophilia"],"correctIndex":0,"explanation":"ESR is a nonspecific marker that may rise with inflammation, infection and other conditions.","explanationNe":"ESR nonspecific marker हो र inflammation, infection लगायतमा बढ्न सक्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"The principle of the Sahli method for hemoglobin estimation is formation of:","translation":"Sahli method मा hemoglobin estimation को principle के हो?","options":["Acid hematin","Oxyhemoglobin crystal","Fibrin clot","Methylene blue complex"],"correctIndex":0,"explanation":"Hemoglobin is converted to brown acid hematin and compared colorimetrically.","explanationNe":"Hemoglobin लाई brown acid hematin मा बदली color comparison गरिन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A peripheral blood smear is commonly stained with:","translation":"Peripheral blood smear सामान्यतया कुन stain ले stain गरिन्छ?","options":["Leishman or Wright-Giemsa stain","India ink only","Lugol iodine only","Albert stain only"],"correctIndex":0,"explanation":"Romanowsky-type stains show blood cell morphology and differential features.","explanationNe":"Romanowsky-type stain ले blood cell morphology र differential feature देखाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"The buffy coat contains mainly:","translation":"Buffy coat मा मुख्यतः के हुन्छ?","options":["Leukocytes and platelets","Only RBCs","Only plasma proteins","Only hemoglobin"],"correctIndex":0,"explanation":"After centrifugation, the buffy coat layer contains WBCs and platelets.","explanationNe":"Centrifuge पछि buffy coat मा WBC र platelet हुन्छन्।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"Packed cell volume (hematocrit) represents the:","translation":"Packed cell volume (hematocrit) ले के जनाउँछ?","options":["Proportion of blood volume occupied by RBCs","Total plasma protein","Platelet concentration","WBC percentage only"],"correctIndex":0,"explanation":"Hematocrit is the fraction of whole blood volume occupied by red cells.","explanationNe":"Hematocrit भनेको whole blood volume मा RBC ले ओगटेको हिस्सा हो।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"The reticulocyte count is useful for assessing:","translation":"Reticulocyte count कुन मूल्यांकन गर्न उपयोगी हुन्छ?","options":["Bone marrow response to anemia","ABO blood group","Platelet function only","Serum sodium"],"correctIndex":0,"explanation":"Reticulocytes indicate recent marrow RBC production and response.","explanationNe":"Reticulocyte ले हालैको marrow RBC production र response जनाउँछ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"Sickle cell disease is associated with abnormal:","translation":"Sickle cell disease कुन abnormal hemoglobin सँग सम्बन्धित छ?","options":["Hemoglobin S","Hemoglobin A2 only","Hemoglobin F only","Hemoglobin C in every case"],"correctIndex":0,"explanation":"HbS polymerizes under deoxygenated conditions, causing sickling of RBCs.","explanationNe":"Oxygen कम हुँदा HbS polymerize भएर RBC sickle आकारमा बदलिन सक्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"Thalassemia is characterized by reduced synthesis of:","translation":"Thalassemia मा कुन chain synthesis कम हुन्छ?","options":["One or more globin chains","Heme iron only","Platelet proteins","Leukocyte enzymes"],"correctIndex":0,"explanation":"Thalassemias are inherited disorders with reduced alpha- or beta-globin chain production.","explanationNe":"Thalassemia inherited disorder हो जसमा alpha वा beta globin chain उत्पादन घट्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"Auer rods may be seen in:","translation":"Auer rod कुन अवस्थामा देखिन सक्छ?","options":["Some acute myeloid leukemia cells","Normal mature RBCs","Platelets in all cases","Iron deficiency only"],"correctIndex":0,"explanation":"Auer rods are needle-like inclusions in myeloid blasts and support myeloid lineage.","explanationNe":"Auer rod myeloid blast मा देखिने needle-like inclusion हो।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"The Philadelphia chromosome is classically associated with:","translation":"Philadelphia chromosome मुख्यतः कुनसँग सम्बन्धित छ?","options":["Chronic myeloid leukemia","Iron deficiency anemia","Hemophilia A","Immune thrombocytopenia"],"correctIndex":0,"explanation":"The BCR::ABL1 fusion is characteristic of CML and some other leukemias.","explanationNe":"BCR::ABL1 fusion CML र केही अन्य leukemia मा देखिन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A bone marrow aspirate is commonly used to evaluate:","translation":"Bone marrow aspirate कुन मूल्यांकन गर्न प्रयोग हुन्छ?","options":["Hematopoietic cells and marrow disorders","Blood glucose only","Serum bilirubin only","Urine sediment"],"correctIndex":0,"explanation":"Marrow aspirate permits cytologic assessment of hematopoietic cells.","explanationNe":"Marrow aspirate ले hematopoietic cell को cytologic मूल्यांकन गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"ABO blood group is determined by antigens on:","translation":"ABO blood group कुन antigen का आधारमा निर्धारण हुन्छ?","options":["Red blood cell surface","Platelet nucleus","Serum albumin","WBC mitochondria"],"correctIndex":0,"explanation":"ABO groups depend on A and/or B antigens on RBC membranes.","explanationNe":"ABO group RBC membrane मा A र/वा B antigen अनुसार हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"Group O red cells normally have which ABO antigens?","translation":"Group O RBC मा कुन ABO antigen हुन्छ?","options":["Neither A nor B","A only","B only","Both A and B"],"correctIndex":0,"explanation":"Group O RBCs lack A and B antigens; plasma usually contains anti-A and anti-B.","explanationNe":"Group O RBC मा A र B antigen हुँदैन; plasma मा सामान्यतया anti-A र anti-B हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"The Rh(D) positive blood group indicates presence of:","translation":"Rh(D) positive हुनुको अर्थ कुन antigen उपस्थित छ?","options":["D antigen","A antigen","B antigen","H antigen only"],"correctIndex":0,"explanation":"Rh positive means the D antigen is detected on red cells.","explanationNe":"Rh positive भन्नाले RBC मा D antigen detect हुनु हो।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"Crossmatching before transfusion is performed to:","translation":"Transfusion अघि crossmatch किन गरिन्छ?","options":["Check donor-recipient serologic compatibility","Measure hemoglobin concentration","Count reticulocytes","Determine ESR"],"correctIndex":0,"explanation":"Compatibility testing helps detect clinically significant antibodies and incompatible donor cells.","explanationNe":"Compatibility test ले clinically significant antibody र incompatible donor cell पत्ता लगाउन मद्दत गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"The direct antiglobulin test (DAT) detects:","translation":"Direct antiglobulin test (DAT) ले के detect गर्छ?","options":["Antibody or complement attached to RBCs in vivo","Free glucose in serum","Platelet aggregation","Fibrinogen concentration"],"correctIndex":0,"explanation":"DAT detects immunoglobulin and/or complement coating red cells within the body.","explanationNe":"DAT ले शरीरभित्र RBC मा लागेको immunoglobulin र/वा complement detect गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"The indirect antiglobulin test (IAT) is used to detect:","translation":"Indirect antiglobulin test (IAT) ले के detect गर्छ?","options":["Unexpected antibodies in serum/plasma","Only RBC morphology","Only platelet count","Serum electrolytes"],"correctIndex":0,"explanation":"IAT detects antibodies in patient serum that react with reagent red cells in vitro.","explanationNe":"IAT ले patient serum मा reagent RBC सँग react गर्ने antibody detect गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"Which blood component is most appropriate for a patient with symptomatic severe anemia when indicated?","translation":"Indicated symptomatic severe anemia मा कुन blood component उपयुक्त हुन्छ?","options":["Packed red blood cells","Platelet concentrate only","Fresh frozen plasma only","Cryoprecipitate only"],"correctIndex":0,"explanation":"Packed RBCs increase oxygen-carrying capacity; transfusion depends on clinical assessment.","explanationNe":"Packed RBC ले oxygen-carrying capacity बढाउँछ; transfusion clinical assessment अनुसार हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"Fresh frozen plasma primarily provides:","translation":"Fresh frozen plasma ले मुख्यतः के प्रदान गर्छ?","options":["Coagulation factors","Red cells for oxygen transport","Platelets only","White cells only"],"correctIndex":0,"explanation":"FFP contains multiple plasma coagulation factors and is used for selected indications.","explanationNe":"FFP मा विभिन्न plasma coagulation factor हुन्छन् र निश्चित indication मा प्रयोग हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"Platelet concentrates are used primarily to:","translation":"Platelet concentrate मुख्यतः किन प्रयोग हुन्छ?","options":["Treat or prevent bleeding due to low/ dysfunctional platelets when indicated","Correct isolated iron deficiency","Replace albumin","Treat hyperglycemia"],"correctIndex":0,"explanation":"Platelet transfusion is used for selected thrombocytopenia or platelet dysfunction situations.","explanationNe":"Platelet transfusion निश्चित thrombocytopenia वा platelet dysfunction मा प्रयोग हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"Which practice helps prevent specimen clotting in an EDTA CBC tube?","translation":"EDTA CBC tube मा clot नबन्न कुन अभ्यास उपयोगी हुन्छ?","options":["Gently invert the tube promptly after collection","Shake vigorously","Leave tube uncapped for hours","Add water"],"correctIndex":0,"explanation":"Gentle mixing by inversion distributes anticoagulant without damaging cells.","explanationNe":"Collection पछि हल्का inversion ले anticoagulant मिसाउँछ र cell damage कम गर्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A clotted EDTA sample is unsuitable for CBC mainly because:","translation":"Clotted EDTA sample CBC का लागि अनुपयुक्त किन हुन्छ?","options":["Cells and platelets may be trapped, causing inaccurate counts","Clot increases sample volume accurately","It guarantees normal counts","It removes all plasma interference"],"correctIndex":0,"explanation":"Clotting can trap cells and consume platelets, leading to unreliable hematology results.","explanationNe":"Clot हुँदा cell र platelet फस्न सक्छन् र count unreliable हुन्छ।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"Which instrument principle is commonly used by automated hematology analyzers to count cells?","translation":"Automated hematology analyzer मा cell count का लागि कुन principle सामान्य छ?","options":["Electrical impedance and/or optical methods","Flame test only","ELISA only","Westergren sedimentation only"],"correctIndex":0,"explanation":"Many analyzers use impedance, optical scatter, fluorescence or combinations.","explanationNe":"धेरै analyzer ले impedance, optical scatter, fluorescence वा संयोजन प्रयोग गर्छन्।","topic":"Hematology"}'::jsonb,true),
('bmlt-hematology-mock-026','BMLT','BMLT NHPC Licensing','mock','free',26,'{"question":"Quality control in hematology analyzers is performed to monitor:","translation":"Hematology analyzer मा quality control किन गरिन्छ?","options":["Accuracy and precision of analyzer performance","Patient name spelling only","Blood group only","Room lighting only"],"correctIndex":0,"explanation":"Control materials help identify shifts, trends and imprecision in analyzer results.","explanationNe":"Control material ले analyzer result मा shift, trend र imprecision पत्ता लगाउँछ।","topic":"Hematology"}'::jsonb,true)
